alter table public.walkers add column if not exists review_note text;
create or replace function public.admin_promote_customer_to_walker(p_profile_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'Admin access required'; end if; if not exists(select 1 from public.profiles where id=p_profile_id and role='customer') then raise exception 'Only an existing customer profile can be moved into Walker recruitment review'; end if; insert into public.walkers(id,verification_status,is_active) values(p_profile_id,'pending',false) on conflict(id) do nothing; update public.profiles set role='walker' where id=p_profile_id and role='customer'; return p_profile_id; end $$;
create or replace function public.admin_review_walker(p_walker_id uuid,p_approve boolean,p_note text) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'Admin access required'; end if; if length(btrim(coalesce(p_note,'')))<5 or length(p_note)>2000 then raise exception 'Review note must be 5–2000 characters'; end if; update public.walkers set verification_status=case when p_approve then 'approved' else 'rejected' end,is_active=p_approve,review_note=btrim(p_note) where id=p_walker_id and verification_status='pending'; if not found then raise exception 'Pending Walker candidate not found'; end if; update public.profiles set role=case when p_approve then 'walker' else 'customer' end where id=p_walker_id and role='walker'; end $$;
create or replace function public.admin_suspend_walker(p_walker_id uuid,p_note text) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'Admin access required'; end if; if length(btrim(coalesce(p_note,'')))<5 or length(p_note)>2000 then raise exception 'Suspension reason must be 5–2000 characters'; end if; update public.walkers set verification_status='suspended',is_active=false,review_note=btrim(p_note) where id=p_walker_id and verification_status='approved'; if not found then raise exception 'Approved Walker not found'; end if; update public.profiles set role='customer' where id=p_walker_id and role='walker'; end $$;
revoke all on function public.admin_promote_customer_to_walker(uuid) from public,anon;
revoke all on function public.admin_review_walker(uuid,boolean,text) from public,anon;
revoke all on function public.admin_suspend_walker(uuid,text) from public,anon;
grant execute on function public.admin_promote_customer_to_walker(uuid) to authenticated;
grant execute on function public.admin_review_walker(uuid,boolean,text) to authenticated;
grant execute on function public.admin_suspend_walker(uuid,text) to authenticated;